using System.Text.Json;using JobOrbit.Application.DTOs.Jobs;using JobOrbit.Application.DTOs.RecruiterInterviews;using JobOrbit.Application.DTOs.Notifications;using JobOrbit.Application.Interfaces;using JobOrbit.Domain;using JobOrbit.Domain.Entities;using JobOrbit.Domain.Enums;using Microsoft.EntityFrameworkCore;
namespace JobOrbit.Infrastructure.Persistence.Repositories;
public sealed class RecruiterInterviewRepository(JobOrbitDbContext db, INotificationService notifications):IRecruiterInterviewRepository
{
 public async Task<(RecruiterInterviewOutcome Outcome,int? InterviewId)>CreateAsync(int userId,CreateInterviewRequest request,CancellationToken token=default){var application=await db.JobApplications.Include(x=>x.Interviews).Include(x=>x.CandidateProfile).Include(x=>x.JobPosting).SingleOrDefaultAsync(x=>x.Id==request.ApplicationId&&x.JobPosting.RecruiterProfile.UserId==userId,token);if(application is null)return(RecruiterInterviewOutcome.NotFound,null);if(application.Status!=ApplicationStatus.Shortlisted)return(RecruiterInterviewOutcome.ApplicationNotShortlisted,null);if(application.Interviews.Any(x=>x.Status is InterviewStatus.Scheduled or InterviewStatus.Rescheduled))return(RecruiterInterviewOutcome.DuplicateActiveInterview,null);var interview=new Interview{JobApplicationId=application.Id,ScheduledAt=request.ScheduledAt.ToUniversalTime(),DurationMinutes=request.DurationMinutes,Location=request.Location.Trim(),MeetingUrl=Clean(request.MeetingLink),Notes=Clean(request.Notes),Status=InterviewStatus.Scheduled};application.Status=ApplicationStatus.Interviewing;application.UpdatedAt=DateTime.UtcNow;db.Interviews.Add(interview);await db.SaveChangesAsync(token);Audit(userId,interview.Id,"Create",null,new{interview.ScheduledAt,interview.Status});await db.SaveChangesAsync(token);await NotifyCandidate(application,interview,NotificationTypes.InterviewScheduled,"Interview scheduled",token);return(RecruiterInterviewOutcome.Success,interview.Id);}
 public async Task<PagedResultDto<RecruiterInterviewListItemDto>>ListAsync(int userId,RecruiterInterviewQuery query,CancellationToken token=default){var q=db.Interviews.AsNoTracking().Where(x=>x.JobApplication.JobPosting.RecruiterProfile.UserId==userId);if(!string.IsNullOrWhiteSpace(query.Status)&&Enum.TryParse<InterviewStatus>(query.Status,true,out var status))q=q.Where(x=>x.Status==status);if(query.From.HasValue)q=q.Where(x=>x.ScheduledAt>=query.From.Value.ToUniversalTime());if(query.To.HasValue)q=q.Where(x=>x.ScheduledAt<=query.To.Value.ToUniversalTime());if(!string.IsNullOrWhiteSpace(query.Search)){var term=query.Search.Trim();q=q.Where(x=>(x.JobApplication.CandidateProfile.User.FirstName+" "+x.JobApplication.CandidateProfile.User.LastName).Contains(term)||x.JobApplication.JobPosting.Title.Contains(term)||x.Location!.Contains(term));}q=query.Sort.ToLowerInvariant() switch{"latest"=>q.OrderByDescending(x=>x.ScheduledAt),"created"=>q.OrderByDescending(x=>x.CreatedAt),_=>q.OrderBy(x=>x.ScheduledAt)};var total=await q.CountAsync(token);var rows=await q.Skip((query.Page-1)*query.PageSize).Take(query.PageSize).Select(x=>new{x.Id,x.JobApplicationId,CandidateName=x.JobApplication.CandidateProfile.User.FirstName+" "+x.JobApplication.CandidateProfile.User.LastName,JobTitle=x.JobApplication.JobPosting.Title,x.ScheduledAt,x.DurationMinutes,x.Location,x.MeetingUrl,x.Status}).ToListAsync(token);return new(){Items=rows.Select(x=>new RecruiterInterviewListItemDto{InterviewId=x.Id,ApplicationId=x.JobApplicationId,CandidateName=x.CandidateName,JobTitle=x.JobTitle,ScheduledAt=x.ScheduledAt,DurationMinutes=x.DurationMinutes,Location=x.Location??"",MeetingLink=x.MeetingUrl,Status=x.Status.ToString()}).ToList(),Page=query.Page,PageSize=query.PageSize,TotalItems=total,TotalPages=(int)Math.Ceiling(total/(double)query.PageSize)};}
 public async Task<RecruiterInterviewDetailsDto?>DetailsAsync(int userId,int interviewId,CancellationToken token=default){var x=await db.Interviews.AsNoTracking().Where(i=>i.Id==interviewId&&i.JobApplication.JobPosting.RecruiterProfile.UserId==userId).Select(i=>new{i.Id,i.ScheduledAt,i.DurationMinutes,i.Location,i.MeetingUrl,i.Notes,i.Status,i.CreatedAt,i.UpdatedAt,CandidateId=i.JobApplication.CandidateProfileId,FullName=i.JobApplication.CandidateProfile.User.FirstName+" "+i.JobApplication.CandidateProfile.User.LastName,i.JobApplication.CandidateProfile.User.Email,Phone=i.JobApplication.CandidateProfile.PhoneNumber,JobId=i.JobApplication.JobPostingId,JobTitle=i.JobApplication.JobPosting.Title,Department=i.JobApplication.JobPosting.Department.Name,ApplicationId=i.JobApplicationId,ApplicationStatus=i.JobApplication.Status,i.JobApplication.AppliedAt}).SingleOrDefaultAsync(token);return x is null?null:new(){InterviewId=x.Id,ScheduledAt=x.ScheduledAt,DurationMinutes=x.DurationMinutes,Location=x.Location??"",MeetingLink=x.MeetingUrl,Notes=x.Notes,Status=x.Status.ToString(),CreatedAt=x.CreatedAt,UpdatedAt=x.UpdatedAt,Candidate=new(){CandidateId=x.CandidateId,FullName=x.FullName,Email=x.Email,Phone=x.Phone},Job=new(){JobId=x.JobId,Title=x.JobTitle,DepartmentName=x.Department},Application=new(){ApplicationId=x.ApplicationId,Status=x.ApplicationStatus.ToString(),AppliedOn=x.AppliedAt}};}
 public async Task<RecruiterInterviewOutcome>UpdateAsync(int userId,int interviewId,UpdateInterviewRequest request,CancellationToken token=default){var interview=await Owned(userId,interviewId,token);if(interview is null)return RecruiterInterviewOutcome.NotFound;if(interview.Status is not(InterviewStatus.Scheduled or InterviewStatus.Rescheduled))return RecruiterInterviewOutcome.InvalidTransition;var old=JsonSerializer.Serialize(new{interview.ScheduledAt,interview.Status});var changed=interview.ScheduledAt!=request.ScheduledAt.ToUniversalTime();interview.ScheduledAt=request.ScheduledAt.ToUniversalTime();interview.DurationMinutes=request.DurationMinutes;interview.Location=request.Location.Trim();interview.MeetingUrl=Clean(request.MeetingLink);interview.Notes=Clean(request.Notes);if(changed)interview.Status=InterviewStatus.Rescheduled;Audit(userId,interview.Id,"Update",old,new{interview.ScheduledAt,interview.Status});await db.SaveChangesAsync(token);if(changed)await NotifyCandidate(interview.JobApplication,interview,NotificationTypes.InterviewRescheduled,"Interview rescheduled",token);return RecruiterInterviewOutcome.Success;}
 public async Task<RecruiterInterviewOutcome>CancelAsync(int userId,int interviewId,CancellationToken token=default){var interview=await Owned(userId,interviewId,token);if(interview is null)return RecruiterInterviewOutcome.NotFound;if(interview.Status is not(InterviewStatus.Scheduled or InterviewStatus.Rescheduled))return RecruiterInterviewOutcome.InvalidTransition;var old=interview.Status;interview.Status=InterviewStatus.Cancelled;if(interview.JobApplication.Status==ApplicationStatus.Interviewing)interview.JobApplication.Status=ApplicationStatus.Shortlisted;interview.JobApplication.UpdatedAt=DateTime.UtcNow;Audit(userId,interview.Id,"Cancel",old.ToString(),interview.Status.ToString());await db.SaveChangesAsync(token);await NotifyCandidate(interview.JobApplication,interview,NotificationTypes.InterviewCancelled,"Interview cancelled",token);return RecruiterInterviewOutcome.Success;}
 public async Task<RecruiterInterviewOutcome>CompleteAsync(int userId,int interviewId,CancellationToken token=default){var interview=await Owned(userId,interviewId,token);if(interview is null)return RecruiterInterviewOutcome.NotFound;if(interview.Status is not(InterviewStatus.Scheduled or InterviewStatus.Rescheduled))return RecruiterInterviewOutcome.InvalidTransition;if(interview.ScheduledAt>DateTime.UtcNow)return RecruiterInterviewOutcome.InterviewNotDue;var old=interview.Status;interview.Status=InterviewStatus.Completed;Audit(userId,interview.Id,"Complete",old.ToString(),interview.Status.ToString());await db.SaveChangesAsync(token);return RecruiterInterviewOutcome.Success;}
 public async Task<IReadOnlyList<ShortlistedApplicationDto>>ShortlistedAsync(int userId,CancellationToken token=default)=>await db.JobApplications.AsNoTracking().Where(x=>x.JobPosting.RecruiterProfile.UserId==userId&&x.Status==ApplicationStatus.Shortlisted&&!x.Interviews.Any(i=>i.Status==InterviewStatus.Scheduled||i.Status==InterviewStatus.Rescheduled)).OrderByDescending(x=>x.AppliedAt).Select(x=>new ShortlistedApplicationDto{ApplicationId=x.Id,CandidateName=x.CandidateProfile.User.FirstName+" "+x.CandidateProfile.User.LastName,JobTitle=x.JobPosting.Title}).ToListAsync(token);
 private Task<Interview?>Owned(int userId,int id,CancellationToken token)=>db.Interviews.Include(x=>x.JobApplication).ThenInclude(x=>x.CandidateProfile).Include(x=>x.JobApplication).ThenInclude(x=>x.JobPosting).SingleOrDefaultAsync(x=>x.Id==id&&x.JobApplication.JobPosting.RecruiterProfile.UserId==userId,token);private async Task<int>NotifyCandidate(JobApplication app,Interview interview,string type,string title,CancellationToken token){var managerIds=await db.HiringManagerProfiles.AsNoTracking().Where(x=>x.OrganizationId==app.JobPosting.OrganizationId&&(!x.DepartmentId.HasValue||x.DepartmentId==app.JobPosting.DepartmentId)&&x.User.IsActive).Select(x=>x.UserId).ToListAsync(token);var requests=new List<NotificationCreateRequest>{new(app.CandidateProfile.UserId,type,title,$"Your {app.JobPosting.Title} interview is set for {interview.ScheduledAt:u} at {interview.Location}.",nameof(Interview),interview.Id,$"/candidate/applications/{app.Id}",EventKey:$"interview:{interview.Id}:{type}:{interview.ScheduledAt.Ticks}:candidate")};requests.AddRange(managerIds.Select(managerId=>new NotificationCreateRequest(managerId,type,title,$"An interview for {app.JobPosting.Title} is set for {interview.ScheduledAt:u}.",nameof(Interview),interview.Id,$"/manager/interviews/{interview.Id}",EventKey:$"interview:{interview.Id}:{type}:{interview.ScheduledAt.Ticks}:manager:{managerId}")));return await notifications.CreateManyAsync(requests,token);}private void Audit(int userId,int id,string action,object? oldValue,object? newValue)=>db.AuditLogs.Add(new AuditLog{UserId=userId,EntityName=nameof(Interview),EntityId=id,Action=action,OldValues=Serialize(oldValue),NewValues=Serialize(newValue)});private static string?Serialize(object? value)=>value switch{null=>null,string text=>text,_=>JsonSerializer.Serialize(value)};private static string?Clean(string? value)=>string.IsNullOrWhiteSpace(value)?null:value.Trim();
}
